+++ b/tests/model.test.mjs
@@ -0,0 +1,8 @@
+import fs from 'node:fs';
+for (const f of ['generate-full','generate-starter']) {
+  const s = fs.readFileSync(`src/app/api/${f}/route.ts`,'utf8');
+  if (!s.includes('gpt-5.6-terra')) throw new Error(f+': new model missing');
+  if (/gpt-3\.5-turbo-instruct|max_tokens|temperature|openai\.completions\./.test(s)) throw new Error(f+': legacy shape');
+  if (!s.includes('chat.completions.create')||!s.includes('max_completion_tokens')) throw new Error(f+': chat shape missing');
+}
+console.log('ok');

