diff --git a/test/sdk.test.mjs b/test/sdk.test.mjs
new file mode 100644
index 0000000..f995f79
--- /dev/null
+++ b/test/sdk.test.mjs
@@ -0,0 +1,13 @@
+import assert from 'node:assert';
+import fs from 'node:fs';
+import OpenAI from 'openai';
+const v = JSON.parse(fs.readFileSync('node_modules/openai/package.json','utf8')).version;
+assert(v.startsWith('7.'), 'openai 7.x');
+assert(parseInt(process.versions.node,10) >= 22);
+assert.strictEqual(JSON.parse(fs.readFileSync('package.json','utf8')).engines.node, '>=22');
+let url, body;
+const c = new OpenAI({ apiKey:'x', maxRetries:0, fetch: async (u,i)=>{url=String(u);body=JSON.parse(i.body);
+ return new Response(JSON.stringify({id:'c1',object:'text_completion',choices:[{text:'hi'}]}),{headers:{'content-type':'application/json'}});}});
+const r = await c.completions.create({model:'gpt-3.5-turbo-instruct',prompt:'p',max_tokens:200,temperature:0.7});
+assert(url.endsWith('/completions')); assert.strictEqual(body.max_tokens,200); assert.strictEqual(r.choices[0].text,'hi');
+console.log('ok');
